"""Generate an offline interactive before/after comparison from real game renders."""
from pathlib import Path
import html
root=Path(__file__).resolve().parents[1]
passes=[('v3-baseline','原版'),('v4-light','第4代 · 光影'),('v5-water-sky','第5代 · 水面与天空'),('v6-material','第6代 · 倒角与材质'),('v7-polish','第7代 · 调色与微动'),('v8-botanical','第8代 · 叶片与温室'),('v10-compatible','1.0 · 兼容画质'),('v10-forward','1.0 · 高画质与机关'),('v11-compatible','1.1 · 兼容画质'),('v11-detail','1.1 · 模型、字体与组件'),('v14-compatible','1.4 · 兼容画质'),('v14-forward','1.4 · 修复现场与渲染'),('v15-compatible','1.5 · 兼容画质'),('v15-forward','1.5 · 居中菜单与清爽探索'),('v16-forward','1.6 · 插画序章与海岸'),('v16-compatible','1.6 · 兼容画质')]
passes=[entry for entry in passes if (root/'builds/render-iterations'/entry[0]/'scene-pump-station.png').exists()]
scenes=[('scene-pump-station','旧泵站'),('scene-greenhouse','废弃温室'),('scene-regrowth','回生花园')]
style='''body{margin:0;background:#14292f;color:#e8e5d7;font:16px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:36px 24px}h1{font-size:32px}p{color:#abc0bd}button,select{background:#28444c;color:#e8e5d7;border:1px solid #6f8a84;border-radius:6px;padding:10px;font:inherit}label{margin-right:20px}img{width:100%;display:block}.compare{position:relative;aspect-ratio:8/5;overflow:hidden;margin:20px 0;background:#000}.compare img{position:absolute;inset:0}.compare .after{clip-path:inset(0 0 0 50%)}.divider{position:absolute;left:50%;top:0;bottom:0;width:2px;background:#e9c88d}.tag{position:absolute;top:14px;background:#132930de;padding:5px 14px;color:#fff}.tag.left{left:14px}.tag.right{right:14px}input{width:100%;accent-color:#d8be83}section{border-top:1px solid #47646a;padding:24px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figcaption{margin:8px 0}figure{margin:0}@media(max-width:700px){.grid{grid-template-columns:1fr}}'''
page=f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>废墟里的种子 · 历史渲染对照</title><style>{style}</style><main><h1>从原版到 1.6 · 渲染对照</h1><p>1.6增加插画序章、海岸住宅、长波海面与分枝树木。1.5的清爽探索界面与1.4的修复现场保留。1.2/1.3没有采集实景图，因此不补造这两代图片。</p><p>历代实际实现与引擎渲染。三章固定场景与受控全彩状态；1.4温室镜头为避开前景柱向内侧偏移，不是逐像素同视角对比；云、水纹和微尘随时间运动。以下为受控全彩展示，正常游戏仍从黑白开始。</p>'
page+='<label>场景 <select id="scene">'+''.join(f'<option value="{key}">{name}</option>' for key,name in scenes)+'</select></label>'
page+='<label>与原版比较 <select id="pass">'+''.join(f'<option value="{key}" {"selected" if key=="v16-forward" else ""}>{name}</option>' for key,name in passes[1:])+'</select></label>'
page+='<div class="compare"><img id="before" alt="原版第一人称场景"><img class="after" id="after" alt="新版第一人称场景"><div class="divider" id="divider"></div><span class="tag left">原版</span><span class="tag right" id="tag">1.0</span></div><label for="slider">拖动分界线，比较同一场景</label><input id="slider" type="range" min="0" max="100" value="50">'
for key,name in passes[1:]:
 page+=f'<section><h2>{html.escape(name)}</h2><div class="grid">'
 for scene,title in scenes[:2]:page+=f'<figure><img src="render-iterations/{key}/{scene}.png" loading="lazy" alt="{title}"><figcaption>{title}</figcaption></figure>'
 page+='</div></section>'
page+='''<p>各代目录保留脚本、着色器和配置快照；当前独立桌面软件为1.6.0版；1.5参赛材料为历史归档。历史像素、录像和帧率记录位于verification/history-v11，1.6流程、像素与原生渲染记录位于builds/v16-*.log、render-pixel-v16-*.json及render-iterations/v16-*。没有将历史画面或录制速度作为新版视觉验收及性能承诺。</p></main><script>const scene=document.getElementById('scene'),pass=document.getElementById('pass'),slider=document.getElementById('slider');function refresh(){document.getElementById('before').src='render-iterations/v3-baseline/'+scene.value+'.png';document.getElementById('after').src='render-iterations/'+pass.value+'/'+scene.value+'.png';document.getElementById('tag').textContent=pass.options[pass.selectedIndex].text}function split(){document.getElementById('after').style.clipPath='inset(0 0 0 '+slider.value+'%)';document.getElementById('divider').style.left=slider.value+'%'}scene.onchange=refresh;pass.onchange=refresh;slider.oninput=split;refresh();split();</script></html>'''
(root/'builds/render-comparison.html').write_text(page)
